"""The specification map, docs/spec-map.json, generated by tools/spec_map/generate.py.

The map lists every Arlington object and the features of
tools/spec_map/features.toml with a status in five dimensions (DESIGN.md
section 8). A status is done only when a test marked pytest.mark.spec proves
it, and the map names that test.
"""

from __future__ import annotations

import json
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
GENERATOR = ROOT / "tools/spec_map/generate.py"
MAP = Path("docs/spec-map.json")
FEATURES = Path("tools/spec_map/features.toml")
COMMAND = "python3 tools/spec_map/generate.py"
DIMENSIONS = ("read", "interpret", "create", "edit", "preserve")


def generate(root: Path, *args: str) -> subprocess.CompletedProcess[str]:
    """Run the generator on a repository root."""
    command = [sys.executable, str(GENERATOR), "--root", str(root), *args]
    return subprocess.run(command, capture_output=True, check=False, text=True)  # noqa: S603 - fixed arguments


def copy_root(root: Path) -> Path:
    """Copy what the generator reads and the map to another root, and return it."""
    shutil.copytree(ROOT / "tools/arlington/model", root / "tools/arlington/model")
    shutil.copytree(ROOT / "tests", root / "tests", ignore=shutil.ignore_patterns("assets", "__pycache__"))
    for path in (FEATURES, MAP):
        (root / path).parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(ROOT / path, root / path)
    return root


def features() -> dict[str, dict]:
    """Return the features of the committed map by name."""
    spec_map = json.loads((ROOT / MAP).read_text(encoding="utf-8"))
    return {feature["feature"]: feature for feature in spec_map["features"]}


def test_the_map_is_current() -> None:
    result = generate(ROOT, "--check")
    assert result.returncode == 0, result.stderr


def test_every_arlington_object_has_a_read_status_backed_by_a_named_test() -> None:
    names = sorted(path.stem for path in (ROOT / "tools/arlington/model/tsv").glob("*.tsv"))
    mapped = features()

    assert len(names) == 613
    for name in names:
        read = mapped[name]["read"]
        assert read["status"] in {"done", "engine"}, name
        assert read["tests"] == [f"tests/test_typed_views.py::test_every_key_of_every_object_type_round_trips[{name}]"]
    assert sum(feature["read"]["status"] == "engine" for feature in mapped.values()) == 36


def test_every_named_test_exists() -> None:
    command = [sys.executable, "-m", "pytest", "--collect-only", "-q", "-p", "no:cacheprovider", "tests"]
    collected = subprocess.run(command, capture_output=True, check=True, cwd=ROOT, text=True).stdout.splitlines()  # noqa: S603 - fixed arguments
    tests = {test.partition("[")[0] for test in collected} | set(collected)

    named = {
        test
        for feature in features().values()
        for dimension in DIMENSIONS
        for test in feature[dimension].get("tests", [])
    }
    assert named
    assert named <= tests, sorted(named - tests)


def test_a_done_status_without_a_named_test_fails_the_check(tmp_path: Path) -> None:
    root = copy_root(tmp_path)
    spec_map = root / MAP
    text = spec_map.read_text(encoding="utf-8")
    test = "tests/test_typed_views.py::test_every_key_of_every_object_type_round_trips[Catalog]"
    proved = f'"read": {{"status": "done", "tests": ["{test}"]}}'
    assert proved in text
    spec_map.write_text(text.replace(proved, '"read": {"status": "done"}'), encoding="utf-8")

    result = generate(root, "--check")

    assert result.returncode == 1
    assert (
        result.stderr == f"Catalog is done for read without a named test\n{MAP.as_posix()} is stale; run `{COMMAND}`\n"
    )


def test_done_comes_only_from_a_marked_test(tmp_path: Path) -> None:
    root = copy_root(tmp_path)
    features_path = root / FEATURES
    features_text = features_path.read_text(encoding="utf-8")
    declared = '[features.page-tree]\nclause = "7.7.3"\n'
    features_path.write_text(
        features_text.replace(declared, declared + 'interpret = { status = "done" }\n'), encoding="utf-8"
    )
    result = generate(root, "--check")
    assert result.returncode == 1
    assert result.stderr == "features.page-tree.interpret is done only when a test marked pytest.mark.spec proves it\n"

    features_path.write_text(features_text, encoding="utf-8")
    views = root / "tests/test_typed_views.py"
    marker = '@pytest.mark.spec("arlington", "read", "create", "edit")\n'
    views.write_text(views.read_text(encoding="utf-8").replace(marker, ""), encoding="utf-8")
    result = generate(root, "--check")
    assert result.returncode == 1
    assert result.stderr.startswith("3DActivation has no read status: mark a test that proves it")


def test_markers_and_statuses_the_generator_does_not_understand_are_refused(tmp_path: Path) -> None:
    root = copy_root(tmp_path)
    features_path = root / FEATURES
    features_text = features_path.read_text(encoding="utf-8")
    pages = root / "tests/test_pages.py"
    pages_text = pages.read_text(encoding="utf-8")
    cases = [
        (pages, pages_text.replace('spec("page-tree", "read")', 'spec("page-tree", "render")'), "dimensions among"),
        (pages, pages_text.replace('spec("page-tree", "read")', 'spec("page-trees", "read")'), "page-trees"),
        (features_path, features_text.replace("upstream = 224 }\ncreate", "issue = 224 }\ncreate"), "takes upstream"),
        (features_path, features_text.replace('status = "n/a"', 'status = "maybe"'), "unknown status 'maybe'"),
        (
            features_path,
            features_text.replace('objects = ["EncryptionStandard"]', 'objects = ["NoSuchObject"]'),
            "NoSuchObject",
        ),
        (
            features_path,
            features_text.replace(
                "[features.flate-filter]\n",
                '[features.flate-filter]\nread = { status = "planned", milestone = "Phase 4: Specification" }\n',
            ),
            "but tests prove it",
        ),
        (features_path, features_text.replace('clause = "7.4.6"', 'clause = "7.4.66"'), "does not list: 7.4.66"),
        (features_path, features_text.replace('"7.2" = ', '"7.2.1" = "Unused"\n"7.2" = '), "without a feature: 7.2.1"),
    ]
    for path, broken, message in cases:
        original = path.read_text(encoding="utf-8")
        assert broken != original
        path.write_text(broken, encoding="utf-8")
        result = generate(root, "--check")
        path.write_text(original, encoding="utf-8")
        assert result.returncode == 1, message
        assert message in result.stderr, result.stderr


def test_every_listed_clause_has_a_feature_and_every_feature_a_listed_clause() -> None:
    spec_map = json.loads((ROOT / MAP).read_text(encoding="utf-8"))
    named = {feature["clause"] for feature in spec_map["features"] if "clause" in feature}
    assert named == set(spec_map["clauses"])
    for standard in ("ISO/TS 32001", "ISO/TS 32005", "ISO 19005", "ISO 14289", "ISO 15930", "ISO 16612"):
        assert standard in spec_map["clauses"]


def test_a_feature_takes_the_default_status_only_where_no_test_proves_it() -> None:
    by_name = features()
    assert by_name["flate-filter"]["read"]["status"] == "done"
    assert by_name["lzw-filter"]["read"] == {"status": "planned", "milestone": "Phase 4: Specification"}
